package com.bank.brackets;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.logging.Logger;

// Validates bracketed fee formulas for National Bank of India.
public class BracketValidator {
    private static final Logger log = Logger.getLogger(BracketValidator.class.getName());

    // Closing bracket → expected opening bracket.
    private static final Map<Character, Character> MATCH = Map.of(
            ')', '(', ']', '[', '}', '{');

    // Valid parentheses via stack. O(n) time, O(depth) space.
    public boolean isValid(String formula) {
        if (formula == null) {
            throw new IllegalArgumentException("formula must not be null");
        }
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : formula.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);                       // opener → push
            } else if (MATCH.containsKey(c)) {
                // Closer: stack top must be the exact matching opener.
                if (stack.isEmpty() || stack.pop() != MATCH.get(c)) {
                    log.info(() -> "'" + formula + "' is INVALID");
                    return false;
                }
            }
            // Non-bracket characters (digits, operators) are ignored.
        }
        boolean balanced = stack.isEmpty();          // leftover opener → invalid
        log.info(() -> "'" + formula + "' is " + (balanced ? "VALID" : "INVALID"));
        return balanced;
    }
}
