package com.bank.brackets;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: validate bracketed fee formulas.
public class BracketValidatorDemo {
    private static final Logger log = Logger.getLogger(BracketValidatorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        BracketValidator validator = new BracketValidator();

        log.info(() -> "Result = " + validator.isValid("{[(1+2)*3]}"));  // true
        log.info(() -> "Result = " + validator.isValid("([)]"));          // false (crossed)
        log.info(() -> "Result = " + validator.isValid("(("));            // false (unclosed)
    }
}
